import{_ as o,o as r,c as a,ai as e}from"./chunks/framework.BBSijY9B.js";const h=JSON.parse('{"title":"常见问题","description":"安装设置、用量额度、服务故障、网站拦截、多 Bot 分享与隐私安全，近 30 个高频问题的直接答案。","frontmatter":{"related":["/basics/safety-approvals","/start/what-is-grok-bot"],"title":"常见问题","description":"安装设置、用量额度、服务故障、网站拦截、多 Bot 分享与隐私安全，近 30 个高频问题的直接答案。","section":"faq","order":1,"tags":["FAQ","常见问题","故障排查","隐私"],"sources":["https://docs.x.ai/grok-bot/overview","https://docs.x.ai/grok-bot/faq","https://cursor.com/help/grok-bot/faqs","https://cursor.com/docs/grok-bot/work","https://docs.x.ai/grok-bot/approvals-security-and-privacy","https://x.ai/changelog/bot","https://docs.x.ai/grok-bot/tag-on-x","https://x.com/bot/status/2112252507762368684"],"wordCount":2227,"readingTime":6,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"常见问题 | WANGXXXL"}],["meta",{"property":"og:description","content":"安装设置、用量额度、服务故障、网站拦截、多 Bot 分享与隐私安全，近 30 个高频问题的直接答案。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/faq/faq"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/faq-faq-ba63fca648.png"}],["meta",{"property":"og:image:alt","content":"常见问题 · WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"常见问题 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"安装设置、用量额度、服务故障、网站拦截、多 Bot 分享与隐私安全，近 30 个高频问题的直接答案。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/faq-faq-ba63fca648.png"}],["meta",{"name":"twitter:image:alt","content":"常见问题 · WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/faq/faq"}]]},"headers":[],"relativePath":"faq/faq.md","filePath":"faq/faq.md","lastUpdated":1792514041000}'),n={name:"faq/faq.md"};function s(p,t,i,g,l,c){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="安装与设置" tabindex="-1">安装与设置 <a class="header-anchor" href="#安装与设置" aria-label="Permalink to &quot;安装与设置&quot;">​</a></h2><p><strong>Q：在哪些设备上能用？</strong> 官方文档列出的平台：</p><ul><li>macOS（Apple 芯片和 Intel 都行）</li><li>Windows（x64 和 Arm64）</li><li>Linux（x64 和 Arm64，有 <code>.deb</code>、<code>.rpm</code> 和 AppImage 三种安装包）</li><li>iPhone（iOS 18 及以上），iPad（iPadOS 18 及以上）</li><li>Android 9 及以上</li></ul><p>同一个账号登录后，Bot 和对话在各设备之间同步。手机上用同一个账号登录即可，不需要重新订阅。</p><p><strong>Q：Grok Bot 和 Grok 聊天 App 是一回事吗？</strong> 不是，是两个不同的应用。Grok App 里的额度提示、付款墙和 Grok Bot 无关；Grok Bot 的用量在 Grok Bot 应用的 <strong>设置 → Usage &amp; Billing</strong> 里看。</p><p><strong>Q：能自己选模型吗？</strong> 不能。Grok Bot 会为每个任务自动选择模型，没有模型选择器。</p><p><strong>Q：界面能改成中文吗？</strong> 能。在设置里选 <strong>Language</strong>。桌面端可以选「跟随系统」，有 20 多种语言，包括简体和繁体中文。</p><p><strong>Q：需要什么订阅？</strong> Grok Bot 需要符合条件的订阅方案才能使用，相关方案和价格仍在调整中。本站不列具体价格和套餐名称，请以官方最新说明为准。</p><p><strong>Q：能用语音吗？</strong> 能。桌面端按 <code>Cmd/Ctrl + D</code> 语音输入；手机上点听写按钮。也可以发起语音聊天，Bot 还能回你语音消息。</p><p>带操作按钮的 iPhone 还可以<strong>一按就开始语音聊天</strong>：把 Grok Bot App 更新到 1.16 并打开一次，再到 <strong>设置 → 操作按钮 → 快捷指令</strong>，搜 &quot;Grok Bot&quot;，选 <strong>Start Voice Chat</strong>。没有操作按钮的机型，可以用&quot;轻点背面&quot;或 Siri 运行同一个快捷指令，见<a href="/daily/2026-10-21-iphone-action-button">日更：iPhone 操作按钮一按就和 Bot 对话</a>。</p><p><strong>Q：能在 X 上直接把帖子交给 Bot 吗？</strong> 能。回复那条帖子时写 <code>@bot</code> 加上你的要求，比如&quot;@bot 把这条里提到的工具整理成表格&quot;，你的主 Bot 就会收到帖子和要求并开工，结果留在 Grok Bot App 里，X 上只有一句确认。前提是在 grok.com 把 X 账号连到 Grok 账号，并且至少有一个自己的 Bot。@bot 没回复就说明没转过去，常见原因（地区未开放、同时 @ 了 @grok、帖子带视频等）见<a href="/daily/2026-10-21-tag-bot-on-x">日更：回复一句 @bot 就交给你的 Bot</a>。</p><p><strong>Q：我该先建几个 Bot？</strong> 一个就够。先让它把一件具体的事做好，等工作明显分成几块时再拆，见<a href="/automation/multi-bot-teamwork">多 Bot 分工协作</a>。</p><p><strong>Q：关掉电脑，Bot 还会干活吗？</strong> 会。任务在云电脑上运行，关掉应用、合上电脑或锁屏手机都不影响正在进行的工作和例程。</p><p>例外是<strong>要在你自己电脑上做的事</strong>：电脑睡着了，Bot 就连不上它。Mac 上光设置&quot;息屏不睡眠&quot;还不够，macOS 的 App Nap 也会让 Grok Bot App 暂停，要一起关掉，做法见<a href="/basics/local-computer">在自己电脑上干活</a>。</p><h2 id="用量与额度" tabindex="-1">用量与额度 <a class="header-anchor" href="#用量与额度" aria-label="Permalink to &quot;用量与额度&quot;">​</a></h2><p><strong>Q：Bot 突然不回复，提示用量用完了，是坏了吗？</strong> 不是。Grok Bot 的用量按周期发放（官方说明为每周重置）。用完后可以等待重置，或按官方渠道增加额度。具体规则以官方最新说明为准。</p><p><strong>Q：怎么省用量？</strong></p><ul><li>例程频率够用就好，简报一天一次通常足够。</li><li>事件触发写得窄一些，不要&quot;每条消息都处理&quot;。</li><li>调研任务说明&quot;快速版&quot;还是&quot;深度版&quot;。</li><li>有连接器就用连接器，比反复操作网页更省。</li><li>例程第一步先查&quot;有没有新内容&quot;，没有就直接结束。</li><li>规则固定的抓数、比对写成脚本定时跑，只把变化交给 Bot；定型的重活交给 Codex CLI、Claude Code 这类命令行工具，Bot 只派活和验收。详见<a href="/daily/2026-10-21-bot-as-foreman">让 Bot 当工头：三层分工法</a>。</li></ul><p><strong>Q：设了花费上限，任务会被立刻中断吗？</strong> 不一定。官方说明上限不会中断正在运行的任务，因此可能略微超出。</p><h2 id="服务故障与排查" tabindex="-1">服务故障与排查 <a class="header-anchor" href="#服务故障与排查" aria-label="Permalink to &quot;服务故障与排查&quot;">​</a></h2><p><strong>Q：怎么判断是不是 Grok Bot 挂了？</strong> 打开 <a href="https://status.cursor.com" target="_blank" rel="noopener noreferrer">status.cursor.com</a> 看 Grok Bot 那一行，应用里不显示服务状态。有故障时<strong>不要重置云电脑、不要重装应用</strong>，两者都修不好服务端问题，重置还可能丢掉最近的改动。等恢复后重发消息即可。完整排查顺序见日更：<a href="/daily/2026-10-20-bot-not-replying">Bot 不回复了？按这个顺序排查</a>。</p><p><strong>Q：我的聊天或 Bot 不见了？</strong> 通常没有被删。依次：完全退出再打开 → 在另一台设备上看 → 侧边栏底部的 <strong>Hidden Bots</strong> → 确认登录的是同一个账号。不要用恢复或重置去找。</p><p><strong>Q：提示云电脑磁盘空间不足？</strong> 说的是 Bot 的云电脑，不是你的笔记本。新版本里 Bot 会提醒一次、列出最大的文件，<strong>你同意后才删</strong>，聊天记录不受影响。</p><p><strong>Q：要联系官方支持，准备什么？</strong> 账号邮箱、版本信息（账户菜单 → Support → About → Copy version info）、截图、请求 ID（右键那条消息 → Copy request ID）。</p><h2 id="云电脑卡住了" tabindex="-1">云电脑卡住了 <a class="header-anchor" href="#云电脑卡住了" aria-label="Permalink to &quot;云电脑卡住了&quot;">​</a></h2><p><strong>Q：Bot 一直显示在工作，但没有进展？</strong> 先打开电脑预览看看它停在哪一步，常见原因是遇到登录页、验证码或弹窗。可以直接问：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你现在卡在哪一步？截图给我看，并说明需要我做什么。</span></span></code></pre></div><p><strong>Q：云电脑连不上怎么办？</strong> 从轻到重：重试或重新打开对话 → 重启应用并检查更新 → 使用界面提供的恢复选项 → 在设置中更新云电脑 → 最后才考虑重置。对话记录不受影响，但重置前未保存的最新改动可能丢失。详见<a href="/basics/cloud-computer">云电脑怎么用</a>。</p><p><strong>Q：某个网站总是登录失效？</strong> 有些网站会定期要求重新验证。让 Bot 遇到时暂停并通知你，由你接管完成登录，不要让它想办法绕过。</p><p><strong>Q：网站拦截 Bot、一直超时或连接出错？</strong> 有些网站会拒绝来自云电脑共享网络的连接，这时更新、恢复、重置都没用。到 <strong>设置 → Computer → Your computer</strong> 打开 <strong>Route traffic through this computer</strong>，让 Bot 的浏览器走你自己电脑的网络（需要桌面端开着）；或者用 <strong>Execution on this computer</strong> 让命令在你的电脑上执行。详见日更：<a href="/daily/2026-10-20-site-blocks-bot">网站总拦 Bot、一直超时？</a></p><p><strong>Q：审批卡片过期了，动作没执行？</strong> 例程或其他 Bot 发起的工作中的审批，大约 10 分钟无人处理就会过期。让 Bot 重试即可；常用且可信的动作可以考虑&quot;始终允许&quot;，或打开通知避免错过。</p><h2 id="多-bot-与分享" tabindex="-1">多 Bot 与分享 <a class="header-anchor" href="#多-bot-与分享" aria-label="Permalink to &quot;多 Bot 与分享&quot;">​</a></h2><p><strong>Q：几个 Bot 能同时干活吗？</strong> 能。它们可以并行思考、调用连接器、处理文件。每个 Bot 在共享的云电脑上有自己的屏幕，但一个 Bot 同一时间只能在自己屏幕上做一件操作电脑的任务。</p><p><strong>Q：能把我调教好的 Bot 分享给别人吗？</strong> 能。在分享菜单里选 <strong>Create template</strong>，再 <strong>Copy link</strong>，可以选公开链接或仅团队可见。对方拿到的是一份副本：<strong>拿不到你的电脑、登录状态和聊天记录</strong>，但能看到 Bot 的配置。所以分享前把描述里的密钥、内部信息删干净。</p><p><strong>Q：能演示给 Bot 看，让它学会吗？</strong> 在提供「Teach a task」的版本里可以：在电脑视图里录一段浏览器操作（最长 10 分钟），Bot 会把它整理成一份技能草稿，你审一遍、测一次再用。这个功能是逐步开放的，你那里没有也正常。</p><h2 id="隐私与安全" tabindex="-1">隐私与安全 <a class="header-anchor" href="#隐私与安全" aria-label="Permalink to &quot;隐私与安全&quot;">​</a></h2><p><strong>Q：我的密码会被 Bot 看到吗？</strong> 按照设计，密码、验证码通过接管电脑或安全表单输入，不进入聊天记录。请不要在对话里直接发送密码。</p><p><strong>Q：不同 Bot 之间的数据是隔离的吗？</strong> 对话和记忆按 Bot 区分，但云电脑上的文件、浏览器登录和命令行凭证是你所有 Bot 共享的。不同用户之间则是严格隔离的。</p><p><strong>Q：数据会被用于训练吗？</strong> 遵循你账号的隐私设置和官方隐私政策，以官方最新说明为准。</p><p><strong>Q：不再使用某个项目时要做什么？</strong> 暂停或删除相关例程 → 退出网站登录 → 移除连接器并撤销授权 → 删除云电脑上的敏感文件 → 隐藏或删除 Bot。注意：删除 Bot 不会自动清除共享电脑上的文件。</p><div class="tip custom-block"><p class="custom-block-title">找不到答案？</p><p>直接问你的 Bot：&quot;这个功能在哪里设置？&quot;它可以帮你查官方文档。涉及账号和订阅计费的问题，以官方帮助中心为准。</p></div>',42)])])}const u=o(n,[["render",s]]);export{h as __pageData,u as default};
